-- Sound Library (founder 10-06): admin > Design > Sound Library, modeled on the Art Library
-- (docs/sql/20261005-art-library.sql + 20261005-art-reviews.sql).
-- NOT APPLIED. Apply by hand (psql, after a backup) when the founder says so; until then the page still lists and
-- plays every sound, and says reviews need this file.
--
-- sound_assets = one row per CANDIDATE: every event in every game (from the Sound Lab, docs/design/brand/sounds/
-- build-lab.py) has a 'now' candidate (exactly what ships today: live = true; silent when nothing plays) plus the
-- lab's options ('a', 'b', 'c'; grid events like the hero laughs have one candidate per set). id =
-- '<section>/<event>/<option>', e.g. 'classic/win/b'. The seed block at the bottom is generated by
-- docs/design/brand/sounds/export-sound-catalog.py (re-run it, then re-apply this file, when the lab changes).
--
-- Reviews use the Art Library's approvers (public.art_reviewers: BMT + JP), so there is one list of who signs off.
-- sound_reviews = one row per (candidate, reviewer), latest decision wins. A reviewer approves ONE candidate per
-- event (approving another clears their earlier approve on that event). A candidate is 'approved' only when every
-- art_reviewers row approves it; any 'reject' makes it 'rejected'; any 'changes' keeps it 'draft'. 'shipped' is
-- set when a pick ships. The rule lives in apps/web/lib/admin/sound-library.ts (+ art-review.ts reviewStatus) and
-- is applied by POST /api/admin/sounds/review, which writes sound_assets.status / decided_at.
--
-- sound_feedback = notes on one candidate (asset_id) or on a whole area (scope, e.g. 'game:classic', 'event:app/intro').
-- Claude reads the unresolved ones with:  select * from public.sound_open_feedback;
-- Approved picks become make-sounds.py PICKS rows with:  apps/server/node_modules/.bin/tsx apps/web/scripts/sound-picks.ts  (dry run).
--
-- Access: admins only, same test as the art tables (the web admin API uses the service role server side).

create table if not exists public.sound_assets (
  id            text primary key,                -- '<section>/<event>/<option>', e.g. classic/win/b
  section       text not null,                   -- lab section: classic, quadword, hubbub, vs, pocket, app ...
  section_title text not null,
  event         text not null,                   -- lab row id: win, loss, key, flip, laugh ...
  event_title   text not null,
  option        text not null,                   -- 'now' (what ships) | 'a' | 'b' | 'c'
  option_name   text not null,                   -- 'Marimba', 'Giggles', 'classic-win' (the shipped name for 'now') ...
  clips         text[] not null default '{}',    -- options/<key>.m4a keys (one, or one per cell of a grid set)
  shipped_name  text,                            -- the shipped sound(s) the event plays today ('now' rows), comma-joined for grids
  live          boolean not null default false,  -- true on the candidate that ships today
  status        text not null default 'draft'
                check (status in ('draft', 'approved', 'rejected', 'shipped')),
  sort          integer not null default 0,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  decided_by    uuid references public.profiles(id) on delete set null,
  decided_at    timestamptz,
  note          text,
  constraint sound_assets_option_check check (option in ('now', 'a', 'b', 'c'))
);

create index if not exists sound_assets_section_idx on public.sound_assets (section);
create index if not exists sound_assets_event_idx   on public.sound_assets (section, event);
create index if not exists sound_assets_status_idx  on public.sound_assets (status);

create table if not exists public.sound_reviews (
  asset_id    text not null references public.sound_assets(id) on delete cascade,
  reviewer_id uuid not null references public.profiles(id) on delete cascade,
  decision    text not null check (decision in ('approve', 'reject', 'changes')),
  note        text,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  unique (asset_id, reviewer_id)
);

create index if not exists sound_reviews_reviewer_idx on public.sound_reviews (reviewer_id);

create table if not exists public.sound_feedback (
  id            uuid primary key default gen_random_uuid(),
  asset_id      text references public.sound_assets(id) on delete set null,
  scope         text,
  author_id     uuid not null references public.profiles(id) on delete cascade,
  body          text not null check (length(btrim(body)) > 0),
  created_at    timestamptz not null default now(),
  resolved_at   timestamptz,
  resolved_by   uuid references public.profiles(id) on delete set null,
  resolved_note text,
  constraint sound_feedback_target_check check (asset_id is not null or scope is not null)
);

create index if not exists sound_feedback_asset_idx on public.sound_feedback (asset_id) where asset_id is not null;
create index if not exists sound_feedback_scope_idx on public.sound_feedback (scope) where scope is not null;
create index if not exists sound_feedback_open_idx  on public.sound_feedback (created_at desc) where resolved_at is null;

alter table public.sound_assets   enable row level security;
alter table public.sound_reviews  enable row level security;
alter table public.sound_feedback enable row level security;

drop policy if exists sound_assets_admin_all   on public.sound_assets;
drop policy if exists sound_reviews_admin_all  on public.sound_reviews;
drop policy if exists sound_feedback_admin_all on public.sound_feedback;

-- Same admin test as the art tables: profiles.role = 'admin' or the is_admin flag.
create policy sound_assets_admin_all on public.sound_assets
  for all to authenticated
  using (exists (select 1 from public.profiles p
                 where p.id = auth.uid() and (p.role = 'admin' or coalesce(p.is_admin, false))))
  with check (exists (select 1 from public.profiles p
                      where p.id = auth.uid() and (p.role = 'admin' or coalesce(p.is_admin, false))));

create policy sound_reviews_admin_all on public.sound_reviews
  for all to authenticated
  using (exists (select 1 from public.profiles p
                 where p.id = auth.uid() and (p.role = 'admin' or coalesce(p.is_admin, false))))
  with check (exists (select 1 from public.profiles p
                      where p.id = auth.uid() and (p.role = 'admin' or coalesce(p.is_admin, false))));

create policy sound_feedback_admin_all on public.sound_feedback
  for all to authenticated
  using (exists (select 1 from public.profiles p
                 where p.id = auth.uid() and (p.role = 'admin' or coalesce(p.is_admin, false))))
  with check (exists (select 1 from public.profiles p
                      where p.id = auth.uid() and (p.role = 'admin' or coalesce(p.is_admin, false))));

revoke all on public.sound_assets   from anon;
revoke all on public.sound_reviews  from anon;
revoke all on public.sound_feedback from anon;

-- Unresolved feedback, newest first: what Claude reads before a sound pass.
create or replace view public.sound_open_feedback with (security_invoker = true) as
select f.id,
       f.asset_id,
       a.section,
       a.event,
       a.event_title,
       a.option,
       a.option_name,
       a.live,
       f.scope,
       p.username as author,
       f.body,
       f.created_at
from public.sound_feedback f
left join public.sound_assets a on a.id = f.asset_id
left join public.profiles     p on p.id = f.author_id
where f.resolved_at is null
order by f.created_at desc;

-- Admins read it through the service-role API; Claude reads it with psql. No client role needs it.
revoke all on public.sound_open_feedback from anon, authenticated;

-- BEGIN SEED (generated by docs/design/brand/sounds/export-sound-catalog.py; re-run it to refresh)
on conflict (id) do update set section = excluded.section, section_title = excluded.section_title, event = excluded.event,
  event_title = excluded.event_title, option = excluded.option, option_name = excluded.option_name, clips = excluded.clips,
  shipped_name = excluded.shipped_name, live = excluded.live, sort = excluded.sort, updated_at = now();
-- END SEED
